import Image from "next/image";
import { db } from "@/lib/db";
import { cn } from "@/lib/utils";
import { PageHeader, Panel } from "@/components/admin/ui";
import { GalleryItemActions, GalleryUploadForm } from "@/components/admin/SmallForms";

const LABEL = { ENGRAVING: "Engraving", B2B_PROJECT: "B2B project", STORE: "Store" } as const;

export default async function AdminGallery() {
  const items = await db.galleryItem.findMany({ orderBy: { createdAt: "desc" } });
  return (
    <>
      <PageHeader title="Engraving & B2B project gallery" description="Photos and videos appear on the Gallery, Engraving and B2B pages as soon as you publish." />
      <Panel title="Upload" className="mb-6"><GalleryUploadForm /></Panel>
      <div className="grid grid-cols-2 gap-4 md:grid-cols-3 xl:grid-cols-4">
        {items.map((g) => (
          <div key={g.id} className={cn("overflow-hidden rounded-lg border border-line bg-white", !g.isPublished && "opacity-50")}>
            <div className="relative aspect-[4/3] bg-paper">
              {g.mediaType === "VIDEO" ? <video src={g.url} className="h-full w-full object-cover" muted preload="metadata" /> : <Image src={g.url} alt={g.title} fill sizes="25vw" className="object-cover" />}
            </div>
            <div className="space-y-1 p-3">
              <p className="text-sm font-medium">{g.title}</p>
              <p className="text-xs text-muted">{LABEL[g.category]} · {g.mediaType.toLowerCase()}</p>
              <GalleryItemActions id={g.id} isPublished={g.isPublished} />
            </div>
          </div>
        ))}
      </div>
      {!items.length && <p className="rounded-lg bg-white p-8 text-center text-sm text-muted">No gallery items yet — upload your first engraving or installation photo above.</p>}
    </>
  );
}
